package com.smarttraining.evaluation.dto;
import com.smarttraining.evaluation.entity.QuizAttempt; import com.smarttraining.evaluation.enums.AttemptStatus; import java.time.LocalDateTime; import java.util.List;
public class QuizAttemptFullResponse { private Long id;private Long quizId;private Long learnerId;private AttemptStatus status;private LocalDateTime startedAt;private LocalDateTime submittedAt;private Integer score;private Integer totalPoints;private Boolean success;private List<QuestionAnswerResponse> answers; public QuizAttemptFullResponse(){} public QuizAttemptFullResponse(QuizAttempt a,List<QuestionAnswerResponse> answers){id=a.getId();quizId=a.getQuizId();learnerId=a.getLearnerId();status=a.getStatus();startedAt=a.getStartedAt();submittedAt=a.getSubmittedAt();score=a.getScore();totalPoints=a.getTotalPoints();success=a.getSuccess();this.answers=answers;} public Long getId(){return id;}public Long getQuizId(){return quizId;}public Long getLearnerId(){return learnerId;}public AttemptStatus getStatus(){return status;}public LocalDateTime getStartedAt(){return startedAt;}public LocalDateTime getSubmittedAt(){return submittedAt;}public Integer getScore(){return score;}public Integer getTotalPoints(){return totalPoints;}public Boolean getSuccess(){return success;}public List<QuestionAnswerResponse> getAnswers(){return answers;} }
